}

solutionCode:
pub fn crescer(mut texto: String, urgente: bool, nivel: i32) -> String {
    if urgente && nivel > 5 {
        texto.push_str("!!!");
    } else {
        texto.push_str("!");
    }
    texto
}

testsCode:
use desafio::crescer;

#[test]
fn testa_o_crescimento_do_urgente_alto() {
    assert_eq!(crescer(String::from("oi"), true, 8), "oi!!!");
}

#[test]
fn testa_o_crescimento_do_urgente_baixo() {
    assert_eq!(crescer(String::from("socorro"), true, 2), "socorro!");
}

#[test]
fn testa_o_crescimento_do_calmo_alto() {
    assert_eq!(crescer(String::from("oi"), false, 8), "oi!");
}
